#include <cstdint>

int process_data_stream(const uint8_t* data, int len) {
    if (len <= 0 || data == nullptr) {
        return 0;
    }

    int processed = 0;
    int i = 0;

    while (i < len) {
        uint8_t c = data[i];

        if (c == '\r') {
            // Handle carriage return
            if (i + 1 < len && data[i + 1] == '\n') {
                // Skip the line feed if it follows a carriage return
                i += 2;
            } else {
                // Just a single carriage return
                i++;
            }
            processed += i - processed;
        } else if (c == '\n') {
            // Handle line feed
            i++;
            processed += i - processed;
        } else {
            // Regular character
            i++;
        }
    }

    return processed;
}
